  "clinic.team.assignedTo": "Whose work they cover",
  "clinic.team.noneAssigned": "Nobody yet, so they see no calendars or earnings.",
  /* 🔴 T13: a non-admin's own row: widening your own reach is the admin's call. */
  "clinic.team.notYourOwn": "Whoever runs the practice sets yours.",
  "clinic.team.saveAssignments": "Save",
