  "dfl.claimBody": "A therapist can write notes about you before you have an account. This is how you take ownership of them, and what you decide on the way.",
  "dfl.claimStep1": "Something is there",
  "dfl.claimStep2": "Prove it is you",
  "dfl.claimStep3": "Enter the code",
  "dfl.claimStep4": "Decide what they keep",
  "dfl.claimStep5": "It is yours",
  "dfl.claimWhy1": "Initials only, and no clinician named. Telling you who holds a record before you have proved who you are would turn this into a way of finding out who is in therapy.",
  "dfl.claimWhy2": "Nothing is looked up until you can receive a message at that number.",
  "dfl.claimWhy3": "The code expires in thirty minutes. Three wrong tries and it stops.",
  "dfl.claimWhy4": "The box starts unchecked. Keeping access is a thing you switch on, never a thing you forget to switch off.",
  "dfl.claimWhy5": "Their notes are still their record. What changed is the profile, which is yours.",
  "dfl.consentTitle": "Giving a therapist access, and taking it back",
  "dfl.consentBody": "Nobody reads your history unless you say so, the answer has a length you choose, and stopping it takes one tap and no explanation.",
  "dfl.consentStep1": "They ask",
  "dfl.consentStep2": "You answer",
  "dfl.consentStep3": "They can read",
  "dfl.consentStep4": "You stop it",
  "dfl.consentStep5": "They cannot",
  "dfl.consentWhy1": "They cannot read a word before you answer. The request itself is all that exists yet.",
  "dfl.consentWhy2": "Three answers, and one of them is no. Saying no changes nothing about your session or what you pay.",
  "dfl.consentWhy3": "While it is on, they read your history. Every read is written into an audit log you can ask for.",
  "dfl.consentWhy4": "One tap. No reason asked, no confirmation of why, and they are not told a reason.",
