  "tmsg.reset.button": "Choose a new password",
  "tmsg.reset.ignore": "If you did not ask for this, nothing has changed and you can ignore this email.",
  "tmsg.radarOff.subject": "You have been taken off the Crisis Radar",
  "tmsg.radarOff.reported": "A patient reported that you did not join a session they had booked and paid for, and the session record shows you did not start it. They have been refunded, and you are off the radar {period}.\n\nIf this is wrong, reply to this email and we will look at it.\n\nGoing on the radar means being ready to take a session within a minute. If you cannot be, switch yourself off. There is no penalty for being unavailable, only for being unavailable while advertised.",
  "tmsg.radarOff.admin": "You are off the Crisis Radar {period}.\n\nReason given: {note}\n\nYour own patients and everything in your portal are unaffected. This only stops new bookings from strangers on the radar. Reply to this email if you think it is wrong.",
  "tmsg.radarOff.abandoned": "A patient booked you on the Crisis Radar, joined the room, and waited {minutes} minutes. You never started the session.\n\nThis has happened before, so you are off the radar {period}. Your own patients and the rest of your portal are unaffected.\n\nBeing on the radar is a promise that you are there. If you cannot be, switch yourself off. There is no penalty for being unavailable, only for being unavailable while advertised as available.\n\nIf you believe this is wrong, reply to this email.",
  "talert.riskTitle": "Risk language detected",
  "talert.riskBodyLive": "Language associated with risk was detected in a live session. Open the session to review.",
  "talert.riskBody": "Language associated with risk was detected in a session. Open the session to review.",
  "talert.riskAction": "Pause and assess directly. If there is imminent risk, follow your local emergency protocol.",
  "talert.aPatient": "A patient",
  "talert.questionnaireTitle": "{name} gave a questionnaire answer that may need a call",
  "talert.questionnaireBody": "An answer on a questionnaire they are filling in now is one we treat as a risk item. It is not quoted here on purpose. Open their record to read it.",
  "talert.journalTitle": "{name} wrote something that may need a call",
  "talert.journalBody": "A journal entry written just now matched the language we watch for ({count} phrases). It is not quoted here on purpose. Open their record to read it.",
  "talert.journalBodyOne": "A journal entry written just now matched the language we watch for (1 phrase). It is not quoted here on purpose. Open their record to read it.",
  "tmsg.waiting.subject": "A patient was waiting for you",
  "tmsg.waiting.bodyBooked": "A patient joined the room for a session booked with you and waited {minutes} minutes. You never started the session, so they left without being seen.\n\nThis is a warning, not a suspension. The first time is usually a laptop that went to sleep or a notification that did not arrive. Please check that notifications and sound are allowed in your browser on the device you keep open.\n\nIf it happens again you will be taken off the Crisis Radar for 24 hours, and for longer after that. A patient left waiting counts the same whether they found you on the radar or not.",
  "tmsg.radarOff.abandonedBooked": "A patient joined the room for a session booked with you and waited {minutes} minutes. You never started the session.\n\nThis has happened before, so you are off the Crisis Radar {period}. Your own patients and the rest of your portal are unaffected.\n\nA patient left waiting counts the same whether they found you on the radar or not.\n\nIf you believe this is wrong, reply to this email.",
  "tmsg.waiting.body": "A patient booked you on the Crisis Radar, joined the room, and waited {minutes} minutes. You never started the session, so they left without being seen.\n\nThis is a warning, not a suspension. The first time is usually a laptop that went to sleep or a notification that did not arrive. Please check that notifications and sound are allowed in your browser on the device you keep open.\n\nIf it happens again you will be taken off the radar for 24 hours, and for longer after that. Being on the radar is a promise that you are there; if you cannot be, switch yourself off. There is no penalty for being unavailable.",
  "tmsg.period.day": "for 24 hours",
  "tmsg.period.days": "for 3 days",
  "tmsg.period.review": "indefinitely, pending review",
  "tmsg.period.hours": "for {hours} hours",
