  "dev.nav.deliveries": "التسليمات",
  /* 🔴 68.23 — الجلسة كاملة، بالترتيب، علنًا. */
  "devs.flow.title": "جلسة من أولها إلى آخرها",
  "devs.flow.body": "ست مكالمات. الترتيب ليس عرفًا: كل واحدة ترفض حتى تتم التي قبلها، لأن حصيلتها وثيقة سريرية وضع إنسان اسمه عليها.",
  "devs.flow.s1": "اسأل مريضك قبل الجلسة",
  "devs.flow.s1Body": "اعرض سؤال الموافقة على واجهتك وأرسل لنا الإجابة. وحتى تفعل، لا نسجّل شيئًا إطلاقًا. ومن يوافق بعد عشر دقائق يُرسَل بالمكالمة نفسها مع إزاحة، وتغطي الملاحظة من تلك اللحظة.",
  "devs.flow.s2": "أرسل لنا الصوت",
  "devs.flow.s2Body": "رفعًا، أثناء الجلسة أو بعدها. فيديوكم لا يغادر بنيتكم أبدًا: كل ما ننتجه يُصنع من الصوت، وغرفة علاج على أقراصنا شيء لم يطلب منا أحد الاحتفاظ به.",
  "devs.flow.s3": "اقرأ التفريغ",
  "devs.flow.s3Body": "نصًّا عاديًّا، ومعه الجملة التي تقول ما الذي سُجّل. تفريغ يبدأ بعد عشر دقائق يبدو تمامًا كجلسة بدأت متأخرة، والفرق مهم.",
  "devs.flow.s4": "اعرض المسودة على معالجك",
  "devs.flow.s4Body": "ملاحظة SOAP مكتوبة من التفريغ، بنص عادي يقبله سجلكم. هي مسودة: هذا ما يسميها هذا الطرف، وهذا ما يسميه اسم الحقل.",
  "devs.flow.s5": "معالجك يعتمد النص",
  "devs.flow.s5Body": "أعد لنا ما اعتمده فعلًا، وقد يختلف عن مسودتنا بأي قدر بما في ذلك كليًا، ومعرّفكم للشخص الذي اعتمده. ملاحظة بلا اسم أحد عليها ليست ملاحظة، ونرفضها.",
  "devs.flow.s6": "سلّم الملخص لمريضك",
  "devs.flow.s6Body": "مكتوب للمريض لا للسجل، ويراجعه المعالج نفسه. ولا يوجد قبل اعتماد الملاحظة، لأن أن يسمع مريض عن علاجه من نموذج بلا أحد بينهما شيء لن نفعله.",
  "devs.copilot": "المساعد، واختيار معالجكم نفسه",
  "devs.copilotBody": "المعالج على منصتكم يفعّله لنفسه، ثم يسأل عن مريض من الجلسات التي أجريتموها معه. نحن لا نقرر من هو المعالج على منصتكم: خيار التفعيل يقول لماذا هو، ومن يناسبه يجده. وكل إجابة تستشهد بمعرّفات جلساتكم، فيُفتح الاستشهاد في واجهتكم أنتم.",
  "devs.midConsent": "الموافقة أثناء الجلسة",
  "devs.midConsentBody": "الحالة الأرجح أن يغفلها التكامل، لأن البناء البديهي صواب أو خطأ. قد يوافق أحدهم بعد عشر دقائق. أرسل الإزاحة ونبدأ من هناك: يقول كل رد إن الجلسة سُجّلت جزئيًا ومتى بدأ ذلك، بدل أن توحي بأننا سمعنا العشر دقائق الأولى.",
  "devs.limit": "الحد لكم، ونتوقف عنده",
  "devs.limitBody": "تحدّدون عدد جلسات شهريًا ولا نتجاوزه أبدًا. ننبّه جهة الاتصال عند 80% و90%. وعند الحد يستمر منتجكم ويتوقف منتجنا: لا تفريغ ولا ملاحظة ولا ملخص ولا مساعد. ولا نحاسبكم على جلسة لم نقم بها، ولا توجد رسوم تجاوز.",
  "dev.nav.usage": "الاستخدام",
  "dev.nav.docs": "المستندات",
