  "tmsg.radarOff.subject": "أُوقف ظهورك على رادار الأزمات",
  "tmsg.radarOff.reported": "أبلغ مريض أنك لم تنضم إلى جلسة حجزها ودفع ثمنها، ويُظهر سجل الجلسة أنك لم تبدأها. رددنا له المبلغ، وأُوقف ظهورك على الرادار {period}.\n\nإن كان هذا خطأ، ردّ على هذا البريد وسنراجعه.\n\nالظهور على الرادار يعني أنك مستعد لبدء جلسة خلال دقيقة. إن لم تكن مستعدًا، أوقف ظهورك بنفسك. لا عقوبة على عدم التوفر، بل على الظهور متاحًا وأنت غير متوفر.",
  "tmsg.radarOff.admin": "أُوقف ظهورك على رادار الأزمات {period}.\n\nالسبب المذكور: {note}\n\nمرضاك وكل ما في بوابتك لم يتأثر، فهذا يوقف فقط الحجوزات الجديدة من الغرباء على الرادار. ردّ على هذا البريد إن رأيت أنه خطأ.",
  "tmsg.radarOff.abandoned": "حجزك مريض على رادار الأزمات، ودخل الغرفة، وانتظر {minutes} دقيقة، ولم تبدأ الجلسة.\n\nحدث هذا من قبل، لذلك أُوقف ظهورك على الرادار {period}. مرضاك وبقية بوابتك لم يتأثروا.\n\nالظهور على الرادار وعد بأنك موجود. إن لم تستطع، أوقف ظهورك بنفسك. لا عقوبة على عدم التوفر، بل على الظهور متاحًا وأنت غير متوفر.\n\nإن رأيت أن هذا خطأ، ردّ على هذا البريد.",
