  "talert.journalBodyOne": "تطابق إدخال في اليوميات كُتب للتو مع العبارات التي نراقبها (عبارة واحدة). لا نقتبسه هنا عن قصد. افتح سجله لقراءته.",
  "tmsg.waiting.subject": "كان مريض ينتظرك",
  "tmsg.waiting.bodyBooked": "دخل مريض الغرفة لجلسة محجوزة معك وانتظر {minutes} دقيقة، ولم تبدأ الجلسة، فغادر دون أن يقابل أحدًا.\n\nهذا تنبيه وليس إيقافًا. في المرة الأولى يكون السبب غالبًا حاسوبًا دخل وضع السكون أو إشعارًا لم يصل. تأكد من السماح بالإشعارات والصوت في المتصفح على الجهاز الذي تتركه مفتوحًا.\n\nإن تكرر ذلك سيُوقف ظهورك على رادار الأزمات 24 ساعة، ثم مدة أطول بعدها. المريض الذي يُترك منتظرًا يُحسب بالطريقة نفسها سواء وجدك على الرادار أم لا.",
  "tmsg.radarOff.abandonedBooked": "دخل مريض الغرفة لجلسة محجوزة معك وانتظر {minutes} دقيقة، ولم تبدأ الجلسة.\n\nحدث هذا من قبل، لذلك أُوقف ظهورك على رادار الأزمات {period}. مرضاك وبقية بوابتك لم يتأثروا.\n\nالمريض الذي يُترك منتظرًا يُحسب بالطريقة نفسها سواء وجدك على الرادار أم لا.\n\nإن رأيت أن هذا خطأ، ردّ على هذا البريد.",
  "tmsg.waiting.body": "حجزك مريض على رادار الأزمات، ودخل الغرفة، وانتظر {minutes} دقيقة، ولم تبدأ الجلسة، فغادر دون أن يقابل أحدًا.\n\nهذا تنبيه وليس إيقافًا. في المرة الأولى يكون السبب غالبًا حاسوبًا دخل وضع السكون أو إشعارًا لم يصل. تأكد من السماح بالإشعارات والصوت في المتصفح على الجهاز الذي تتركه مفتوحًا.\n\nإن تكرر ذلك سيُوقف ظهورك على الرادار 24 ساعة، ثم مدة أطول بعدها. الظهور على الرادار وعد بأنك موجود، فإن لم تستطع أوقف ظهورك بنفسك. لا عقوبة على عدم التوفر.",
